mapper.select:
SELECT T2.BUYOUT_RATE*100 BUYOUT_RATE, TEMP_CHL_RATE.CHL_RATE FROM FIN_PRODUCT T1 LEFT JOIN PA_FIN_PRODUCT_BUYOUT_RATE T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T2.EFF_DATE = T1.VDATE LEFT JOIN ( SELECT TT.FINPROD_ID, SUM( TT.YIELD ) CHL_RATE FROM ( SELECT T11.FINPROD_ID, T11.YIELD * 100 YIELD FROM FIN_CASH_CALC_RULE T11 LEFT JOIN FIN_CASH_INFO T21 ON T21.CASH_ID = T11.CASH_ID LEFT JOIN FIN_PRODUCT T41 ON T41.FINPROD_ID = T11.FINPROD_ID WHERE T21.CASH_TYPE_2 IN ( 'C11', 'C12', 'C13' )
AND T11.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) TT GROUP BY TT.FINPROD_ID ) TEMP_CHL_RATE ON TEMP_CHL_RATE.FINPROD_ID = T1.FINPROD_ID
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
